INSERT INTO `jurusan` (`id`, `judul`, `sub_judul`, `keterangan`, `gambar`, `created_at`, `updated_at`) VALUES
(4, 'Kecantikan Kulit Dan Rambut', 'Dalam Perkembangan zaman yang semakin pesat akan berdampak pula pada kebutuhan gaya hidup setiap orang. Industri Kecantikan menjadi salah satu industri termaju dan tak pernah mati konsumennya karena kebutuhan Fashion sudah menjadi hal utama dalam kehidupan sehari hari.', '<p>adalah&nbsp;<a title=\"Film\" href=\"https://id.wikipedia.org/wiki/Film\">film</a>&nbsp;yang merupakan hasil dari pengolahan gambar tangan sehingga menjadi&nbsp;<a class=\"mw-redirect\" title=\"Gambar\" href=\"https://id.wikipedia.org/wiki/Gambar\">gambar</a>yang bergerak. Pada awal penemuannya, film animasi dibuat dari berlembar-lembar kertas gambar yang kemudian di-\"putar\" sehingga muncul efek gambar bergerak. Dengan bantuan&nbsp;<a title=\"Komputer\" href=\"https://id.wikipedia.org/wiki/Komputer\">komputer</a>&nbsp;dan&nbsp;<a title=\"Grafika komputer\" href=\"https://id.wikipedia.org/wiki/Grafika_komputer\">grafika komputer</a>, pembuatan film animasi menjadi sangat mudah dan cepat. Bahkan akhir-akhir ini lebih banyak bermunculan film animasi&nbsp;<a title=\"3 dimensi\" href=\"https://id.wikipedia.org/wiki/3_dimensi\">3 dimensi</a>&nbsp;daripada film animasi&nbsp;<a title=\"2 dimensi\" href=\"https://id.wikipedia.org/wiki/2_dimensi\">2 dimensi</a>.</p>', '/photos/1/ApX3zyZN.png', '2019-02-20 07:48:48', '2022-01-20 03:32:24'),
(5, 'Multimedia', 'Dalam kemajuan teknologi dan informatika peran sentuhan multimedia menjadi keharusan dalam berbagai hal, baik usaha usaha kecil, menengah sampai perusahaan besar membutuhkan tenaga multimedia sebagai penunjang dalam hal desain,advertising, percetakan maupun animasi.', '<p>Rekayasa Perangkat Lunak</p>', '/photos/1/ApX3zyZN.png', '2019-02-20 07:50:08', '2022-01-20 03:32:10'),
(6, 'Produksi Siaran Program Televisi', 'Industri Televisi adalah salah satu industri yang mempunyai basis massa tetap dari tahun ketahun, selalu berkembang pada setiap zaman baik tingkat nasional hingga local, dari konvensional hingga digital. Maka dari itu pengembangan talenta muda kreatif pada bidang ini dirasa perlu terus dilakukan demi menjawab permintaan pasar. ', '<p>Teknik Kendaraan Ringan</p>', '/photos/1/tkr.png', '2019-02-20 07:53:07', '2019-02-20 07:53:07'),
(7, 'Teknik Komputer dan Jaringan', 'Dalam perkembangan Dunia teknologi hari ini, pengetahuan akan komputer menjadi sebuah hal yang sangat wajib dilakukan, hampir semua bidang hari ini sudah terkomputerisasi serta kebutuhan industri dan rumahan tentang Internet dan Jaringan, baik kabel maupun nirkabel menjadi sebuah hal pokok kehidupan sekarang.', '<p>Teknik Pengelasan</p>', '/photos/1/ApX3zyZN.png', '2019-02-20 07:58:15', '2022-01-20 03:31:52'),
(8, 'Rekayasa Perangkat Lunak', 'Revolusi Industri 4.0 adalah sebuah era dimana semua hal konvensional menjadi digital, dalam bidang digital kebutuhan pembuatan perangkat lunak menjadi sangat unggulan, semua perusahaan termaju saat ini adalah perusahaan dibidang piranti lunak baik secara internasional maupun nasional, menjadi sebuah kepastian bahwa program studi Rekayasa Perangkat lunak menjadi Program studi terdepan menjawab kebutuhan zaman.', '<p>Broadcasting&nbsp;Broadcasting&nbsp;Broadcasting</p>', '/photos/1/bc.png', '2019-02-20 08:00:35', '2019-02-20 08:00:35');
INSERT INTO `kalimatbijak` (`id`, `nama`, `gambar`, `kalimat`, `created_at`, `updated_at`) VALUES
(1, 'Abdurrahman Wahid (Gus Dur)', '/photos/1/user.png', 'Semakin tinggi ilmu seseorang, maka semakin besar rasa toleransinya.', '2020-03-29 14:37:42', '2020-03-29 14:37:42'),
(2, 'Pramoedya Ananta Toer', '/photos/1/user.png', 'Seorang terpelajar harus sudah berbuat adil sejak dalam pikiran apalagi dalam perbuatan.', '2020-03-29 14:42:44', '2020-03-29 14:42:44');
