INSERT INTO `timeline` (`id`, `judul`, `body`, `featured`, `link_youtube`, `status`, `posisi`, `created_at`, `updated_at`) VALUES
(4, 'Selayang Pandang', 'SMK Kosgoro Kota Bogor merupakan sekolah berwawasan kebangsaan dan keunggulan teknologi yang berdiri pada tahun 2008  dan mendapatkan SK izin operasional dari kepala Dinas Pendidikan Kota Bogor Nomor 421.5/109 Disdik Tahun 2008.  SMK Kosgoro Kota Bogor mulai menerima siswa/i baru pada tahun 2012 dan  memiliki  lima kompetensi keahlian yaitu Teknik Komputer Jaringan, Rekayasa Perangkat Lunak, Multimedia, Produksi dan Siaran Program Televisian, dan Kecantikan Kulit dan Rambut.', '/photos/1/background3973.jpg', 'https://www.youtube.com/watch?v=hbndJWI5e7g', 'aktif', '1', '2019-02-20 08:30:24', '2021-11-08 13:51:51'),
(5, 'Video Kegiatan Sekolah', 'SMK Kosgoro dibawah binaan Yayasan Dharma Setia Kosgoro, Pada Tahun Ini Kembali Menerima Peserta Didik Baru. Program Keahlian Yang Dibuka Yaitu Bidang Teknik Informasi Dan Komunikasi, Program Pertelevisian, Kecantikan Kulit Dan Rambut Yang Bertujuan Untuk Mempersiapkan Lulusannya Menjadi SDM yang siap menghadapi tuntutan pada era Revolusi Industri 4.0\r\n\r\nSMK Kosgoro Mendapatkan Izin Operasional dari kepala dinas pendidikan kota bogor Nomor 421.5/109 Disdik Tahun 2008', '/photos/1/Kunjungan_Industri_ke_TVRI.jpeg', 'https://www.youtube.com/watch?v=mSQOUbBgjD8', 'aktif', '2', '2019-02-20 13:08:44', '2020-03-29 14:21:58');
